{
  title: 'Atoms/Vsk Button Example',
  component: VskButtonExampleComponent,
  tags: ['autodocs','experimental'],
  decorators: [
    applicationConfig({
      providers: [],
    }),
  ],
  parameters: {
    docs: {
      description: {
        component:
          'Референсная кнопка с WCAG‑совместимыми атрибутами и предопределёнными вариантами оформления.',
      },
    },
    actions: {
      handles: ['pressed'],
    },
  },
  argTypes: {
    variant: {
      options: ['primary', 'secondary', 'danger'],
      control: { type: 'radio' },
    },
    size: {
      options: ['md', 'lg'],
      control: { type: 'radio' },
    },
    block: { control: 'boolean' },
    disabled: { control: 'boolean' },
    pressed: { action: 'pressed' },
  },
  args: {
    label: 'Отправить заявку',
    variant: 'primary',
    size: 'md',
    ariaLabel: 'Отправить заявку',
    block: false,
    disabled: false,
  },
  render: (args) => ({
    props: args,
    template: `
      <vsk-button-example
        [label]="label"
        [variant]="variant"
        [size]="size"
        [block]="block"
        [disabled]="disabled"
        [ariaLabel]="ariaLabel"
        [ariaDescribedBy]="ariaDescribedBy"
        [ariaControls]="ariaControls"
        [ariaExpanded]="ariaExpanded"
        [ariaPressed]="ariaPressed"
        [ariaLive]="ariaLive"
        (pressed)="pressed($event)"
      ></vsk-button-example>
    `,
  }),
}

{
  parameters: {
    tags: ['autodocs'],
    a11y: {
      options: {
        /*
         * Opt in to running WCAG 2.x AAA rules
         * Note that you must explicitly re-specify the defaults (all but the last array entry)
         * See https://github.com/dequelabs/axe-core/blob/develop/doc/API.md#options-parameter-examples for more details
         */
        runOnly: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'best-practice', 'wcag2aaa'],
      },
      config: {
        rules: [
          { id: 'aria-allowed-attr', enabled: true },
          { id: 'aria-required-attr', enabled: true },
          { id: 'aria-required-children', enabled: true },
          { id: 'aria-required-parent', enabled: true },
          { id: 'aria-roles', enabled: true },
          { id: 'aria-valid-attr', enabled: true },
          { id: 'aria-valid-attr-value', enabled: true },
          { id: 'aria-prohibited-attr', enabled: true },
        ],
      },
    },
    viewport: {
      options: { ...MINIMAL_VIEWPORTS, ...INITIAL_VIEWPORTS },
    },
    controls: {
      matchers: {
       color: /(background|color)$/i,
       date: /Date$/i,
      },
    },
    docs: {
      codePanel: true,
    },
  },
  initialGlobals: {
    viewport: { value: 'ipad', isRotated: false },
  },
}

